// Parse the hub's SSE-framed JSON-RPC reply -> the tool's JSON result. A refusal or tool error THROWS (a 403 is
// never an empty list: a silent chaser that cannot read is worse than a loud one).
const rpcOf = (raw) => {
  const line = String(raw ?? '').split('\n').find((l) => l.startsWith('data:')) ?? '';
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.error) throw new Error(rpc.error.message ?? 'hub error');
  if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'tool error');
  const out = JSON.parse(rpc.result?.content?.[0]?.text ?? '[]');
  if (!Array.isArray(out)) throw new Error('expected a list from the tool');
  return out;
};
const rawOf = (it) => it.json.data ?? it.json.body ?? '';
// One item per client. No clients -> return [] -> the run stops here, silently.
// The internal sentinel client (isInternal) owns our own sites and has no billing: skipped entirely.
// owner_user_id / owner_name (PV-D28 account owner) ride along on every item; absent or blank -> null (no owner set).
const str = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
const clients = rpcOf(rawOf($input.first()));
return clients
  .filter((c) => c && c.id && c.isInternal !== true)
  .map((c) => ({ json: { clientId: c.id, clientName: c.name ?? c.id, ownerUserId: str(c.owner_user_id), ownerName: str(c.owner_name) } }));

