const rawOf = (it) => it.json.data ?? it.json.body ?? '';
// Carry the client context (incl. the account owner) across the contracts.list reply (paired by item index).
const ctx = $('Split clients (skip if none)').all();
return $input.all().map((it, i) => {
  const c = ctx[it.pairedItem?.item ?? i].json;
  return { json: { clientId: c.clientId, clientName: c.clientName, ownerUserId: c.ownerUserId ?? null, ownerName: c.ownerName ?? null, contracts: rpcOf(rawOf(it)) } };
});

// Parse the hub's SSE-framed JSON-RPC reply -> the tool's JSON result. A refusal or tool error THROWS (a 403 is
// never an empty list: a silent chaser that cannot read is worse than a loud one).
const rpcOf = (raw) => {
  const line = String(raw ?? '').split('\n').find((l) => l.startsWith('data:')) ?? '';
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.error) throw new Error(rpc.error.message ?? 'hub error');
  if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'tool error');
  const out = JSON.parse(rpc.result?.content?.[0]?.text ?? '[]');
  if (!Array.isArray(out)) throw new Error('expected a list from the tool');
  return out;
};
const rawOf = (it) => it.json.data ?? it.json.body ?? '';
// The three PV-D28 reminders. Read-only: nothing here sends, countersigns, confirms or rejects.
//   (a) payment claims status=pending, recorded more than 2 days ago        -> waiting on us to confirm
//   (b) contracts status=sent, clientSigned, NOT providerSigned, sent >1 day -> waiting on our countersignature
//   (c) contracts status=sent, NOT clientSigned, sent more than 7 days ago  -> waiting on the client
// ROUTING (PV-D28): (a) and (b) go to the CONFIGURED recipients (owners / finance act on these). (c) goes to THAT
// client's account owner (owner_user_id); a client with no owner set sends its (c) to the configured recipients,
// flagged "no account owner set". One digest per DISTINCT recipient, covering only that recipient's items.
const DAY = 86400000;
const now = Date.now();
const ageMs = (iso) => { const t = Date.parse(iso); return Number.isFinite(t) ? now - t : null; };
const ctx = $('Parse contracts').all();
const per = [];
$input.all().forEach((it, i) => {
  const c = ctx[it.pairedItem?.item ?? i].json;
  const payments = rpcOf(rawOf(it));
  const pay = payments.filter((p) => p.status === 'pending' && (ageMs(p.recordedAt ?? p.createdAt) ?? -1) > 2 * DAY).length;
  const sent = c.contracts.filter((k) => k.status === 'sent');
  const counter = sent.filter((k) => k.clientSigned === true && k.providerSigned === false && (ageMs(k.sentAt) ?? -1) > 1 * DAY).length;
  const unsigned = sent.filter((k) => k.clientSigned === false && (ageMs(k.sentAt) ?? -1) > 7 * DAY).length;
  if (pay + counter + unsigned > 0) per.push({ clientId: c.clientId, clientName: c.clientName, ownerUserId: c.ownerUserId ?? null, pay, counter, unsigned });
});
if (per.length === 0) return []; // nothing qualifies -> stop, no notification
const configured = String($env.BILLING_NOTIFY_USER_IDS || $env.NOTIFY_USER_ID || '').split(',').map((x) => x.trim()).filter(Boolean);
// recipientId -> Map(clientId -> this recipient's slice of that client). Configured recipients are inserted first, so
// they are delivered first; a configured id that is also an account owner gets ONE merged digest, not two.
const buckets = new Map();
const add = (recipientId, c, slice) => {
  if (!buckets.has(recipientId)) buckets.set(recipientId, new Map());
  const m = buckets.get(recipientId);
  const e = m.get(c.clientId) ?? { clientId: c.clientId, clientName: c.clientName, pay: 0, counter: 0, unsigned: 0, noOwner: false };
  e.pay += slice.pay; e.counter += slice.counter; e.unsigned += slice.unsigned; e.noOwner = e.noOwner || slice.noOwner === true;
  m.set(c.clientId, e);
};
let needsConfigured = false;
for (const c of per) {
  const ownerless = !c.ownerUserId;
  // the configured recipients' slice: (a), (b), and (c) only when nobody owns the client
  const cfg = { pay: c.pay, counter: c.counter, unsigned: ownerless ? c.unsigned : 0, noOwner: ownerless && c.unsigned > 0 };
  if (cfg.pay + cfg.counter + cfg.unsigned > 0) {
    needsConfigured = true;
    for (const r of configured) add(r, c, cfg);
  }
}
for (const c of per) {
  if (c.ownerUserId && c.unsigned > 0) add(c.ownerUserId, c, { pay: 0, counter: 0, unsigned: c.unsigned, noOwner: false });
}
if (needsConfigured && configured.length === 0) throw new Error('billing digest has content but no recipient: set BILLING_NOTIFY_USER_IDS (or NOTIFY_USER_ID)');
const s = (n, one, many) => n + ' ' + (n === 1 ? one : many);
const href = (id) => '/clients/' + id + '/billing';
const digest = (entries) => {
  const list = entries.map((e) => ({ ...e, total: e.pay + e.counter + e.unsigned }));
  list.sort((a, b) => b.total - a.total);
  const sum = (k) => list.reduce((n, c) => n + c[k], 0);
  const pay = sum('pay'), counter = sum('counter'), unsigned = sum('unsigned');
  const parts = [];
  if (pay) parts.push(s(pay, 'payment claim', 'payment claims') + ' waiting over 2 days for confirmation');
  if (counter) parts.push(s(counter, 'contract', 'contracts') + ' signed by the client and waiting over 1 day for our countersignature');
  if (unsigned) parts.push(s(unsigned, 'contract', 'contracts') + ' sent over 7 days ago and still unsigned by the client');
  const shown = list.slice(0, 10).map((c) => c.clientName + ' (' + c.total + (c.noOwner ? ', no account owner set' : '') + ')');
  const more = list.length > 10 ? ', and ' + (list.length - 10) + ' more' : '';
  const body = parts.join('; ') + '. Clients: ' + shown.join(', ') + more + '.';
  return {
    title: 'Billing needs attention',
    href: href(list[0].clientId),
    body,
    severity: 'warning',
    counts: { paymentsAwaitingConfirmation: pay, contractsAwaitingCountersignature: counter, contractsUnsignedByClient: unsigned },
    clients: list.map((c) => ({ id: c.clientId, name: c.clientName, payments: c.pay, countersign: c.counter, unsigned: c.unsigned, ...(c.noOwner ? { noAccountOwner: true } : {}) })),
    links: list.slice(0, 10).map((c) => ({ label: c.clientName, href: href(c.clientId) })),
    ...(list.length === 1 ? { entityType: 'client', entityId: list[0].clientId } : {}),
  };
};
// notify takes ONE recipient user id, so the output is one item per distinct recipient; the notify node runs once per item.
return [...buckets].map(([recipientId, m]) => ({ json: { tenantId: $env.AGENCY_TENANT_ID, recipientId, payload: digest([...m.values()]) } }));

const items = $input.all();
for (const it of items) {
  const raw = it.json.data ?? it.json.body ?? '';
  const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.error) throw new Error(rpc.error.message ?? 'notify failed');
  if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'notify failed');
}
return [{ json: { ok: true, delivered: items.length } }];
